-- Généré par tests/build_guide.lua depuis GUIDE.esES.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.esES = {
    { "h1", "Guía de Panorama" },
    { "p", "Cómo usar Panorama en WoW Forever y cómo configurar HDR en Windows." },
    { "p", "|cffffd100Primero, haz una copia de tus ajustes.|r Panorama cambia ajustes del juego, y quitar el addon no los devuelve a su estado anterior. Antes de cambiar nada, cierra el juego y copia la carpeta |cffffd100WTF|r de tu instalación del juego en un lugar seguro. Para volver atrás, cierra el juego y vuelve a poner esa copia en su sitio." },
    { "h2", "1. Abrir la ventana" },
    { "li", "Escribe |cffffd100/pano|r o haz clic izquierdo en el botón de Panorama del minimapa.", "-" },
    { "li", "En Opciones > AddOns > Panorama también hay un botón que la abre.", "-" },
    { "li", "Arrastra la barra de título para mover la ventana. Escape o el botón de cierre la cierra.", "-" },
    { "p", "El botón del minimapa:" },
    { "li", "El clic izquierdo abre o cierra la ventana.", "-" },
    { "li", "El clic derecho muestra los preajustes, deshacer, rehacer y el reinicio de los gráficos.", "-" },
    { "li", "Arrástralo para moverlo alrededor del minimapa. |cffffd100/pano minimap|r lo muestra u oculta.", "-" },
    { "h2", "2. La ventana" },
    { "row", "Cuadro de búsqueda (arriba a la derecha)", "Escribe una palabra para listar los ajustes que coinciden de todas las pestañas. Bórrala para volver." },
    { "row", "Pestañas", "Calidad, Interfaz, Avanzado (ajustes del juego), luego Filtros, Mis filtros, Ambiente (efectos de Panorama). Se recuerda la pestaña abierta." },
    { "row", "Ajustes avanzados (bajo el título)", "Sin marcar: sin pestañas, una sola página con los preajustes, los ajustes principales de calidad (distancia de visión, niebla volumétrica, sombras, oclusión ambiental, detalle del agua, suavizado de bordes, atenuación de la nitidez), la salida HDR y el brillo máximo, el contraste, el brillo, la distancia de la cámara, el filtro, la intensidad del filtro y el modo de ambiente. Marcado: todas las pestañas y todos los ajustes. En la primera instalación está sin marcar; si ya usabas Panorama, está marcado. La búsqueda siempre encuentra todos los ajustes." },
    { "row", "Deshacer, Rehacer (bajo las pestañas, a la derecha)", "Deshacer anula tu último cambio: control deslizante, casilla, preajuste, filtro, ambiente o Restablecer todo. Rehacer lo recupera. Los últimos 20 cambios se conservan hasta |cffffd100/reload|r." },
    { "row", "Selector de idioma (a la derecha de las pestañas)", "Idioma del juego o uno de diez idiomas. Al cambiarlo se recarga la interfaz." },
    { "row", "Guía (a la izquierda del cuadro de búsqueda)", "Abre esta guía en el juego." },
    { "row", "Preajustes (pestaña Calidad)", "Bajo, Medio, Alto, Extra. Se resalta el preajuste que coincide con tus ajustes." },
    { "row", "Pie", "Aplicar en cada conexión, botón del minimapa, Restablecer todo, reinicio del motor gráfico." },
    { "p", "Haz clic en el título de una sección para plegarla o desplegarla." },
    { "h3", "Una línea de ajuste" },
    { "li", "|cffffd100Control deslizante|r: el valor se escribe al soltar el botón del ratón, no mientras arrastras.", "-" },
    { "li", "|cffffd100Cuadro de valor|r junto al control deslizante: escribe un valor y pulsa Intro o haz clic en otro sitio. Escape cancela, Tab pasa al cuadro siguiente. La coma sirve como separador decimal. El valor se mantiene dentro del rango del control deslizante.", "-" },
    { "li", "|cffffd100Botón Predeterminado|r: devuelve ese ajuste a su valor predeterminado. Pasa el ratón por encima para ver el valor.", "-" },
    { "li", "|cffffd100Marca dorada|r a la izquierda: has cambiado este ajuste.", "-" },
    { "li", "|cffffd100Estrella amarilla|r: un menú del juego también establece este valor. Pasa el ratón por encima para ver cuál. Ese menú no vuelve a leer el valor, así que puede mostrar otro nivel.", "-" },
    { "li", "|cffffd100Línea en gris|r: depende de otro ajuste que está desactivado (por ejemplo, la densidad de la niebla sin niebla volumétrica, la intensidad del tono sin un tono). La línea indica qué ajuste cambiar.", "-" },
    { "li", "Pasa el ratón por una etiqueta para leer su ayuda completa.", "-" },
    { "h2", "3. Preajustes" },
    { "row", "Bajo", "Máximo rendimiento. Poca distancia de visión, sin sombras." },
    { "row", "Medio", "Equilibrado. Buen rendimiento y sombras correctas." },
    { "row", "Alto", "Nivel Alto del juego. Sombras completas, todos los efectos." },
    { "row", "Extra", "Alto, con la mayor distancia de visión." },
    { "p", "Los preajustes solo cambian los ajustes de calidad gráfica de la pestaña Calidad. No tocan la cámara, el ratón, la interfaz, el enfoque, la baja latencia, HDR ni los filtros." },
    { "p", "¿Has cambiado de opinión? |cffffd100Deshacer|r (bajo las pestañas, o |cffffd100/pano undo|r) restaura los ajustes de antes del preajuste." },
    { "h2", "4. Filtros" },
    { "p", "La pestaña Filtros añade efectos sobre la imagen. No cambian ningún ajuste del juego." },
    { "li", "|cffffd100Tono|r: haz clic en una miniatura para aplicarlo al instante (Sepia, Cálido, Frío, Noche, Esmeralda, Crepúsculo). |cffffd100Intensidad del tono|r define su fuerza.", "-" },
    { "li", "|cffffd100Mi filtro|r: usa uno de tus filtros de la pestaña Mis filtros. Sustituye el tono, la viñeta y el grano.", "-" },
    { "li", "|cffffd100Cielo|r: los mismos colores en degradado, completos arriba de la pantalla y más claros abajo. |cffffd100Intensidad del cielo|r define su fuerza.", "-" },
    { "li", "|cffffd100Viñeta|r: oscurece los bordes de la pantalla.", "-" },
    { "li", "|cffffd100Grano|r: grano animado.", "-" },
    { "li", "|cffffd100Barras negras|r: barras superior e inferior, de 0 a 20 % de la pantalla cada una. El juego sigue renderizando lo que ocultan, así que no aumentan la tasa de fotogramas.", "-" },
    { "h3", "Ambiente" },
    { "p", "La pestaña Ambiente cambia sola el tinte, el cielo, la viñeta y el grano según dónde estés." },
    { "li", "|cffffd100Modo|r (parte superior de la pestaña): |cffffd100Desactivado|r (la pestaña Filtros se aplica en todas partes), |cffffd100Día y noche automáticos|r (ver Día y noche más abajo) o |cffffd100Ambiente automático|r. Desactivado por defecto.", "-" },
    { "li", "|cffffd100Ambiente automático|r: estos filtros siguen el lugar y la hora del día. Los valores de la pestaña Filtros siguen guardados y vuelven al cambiar de modo. Sin Ajustes avanzados, la página única solo muestra el modo y el lugar detectado; marca Ajustes avanzados para editar los contextos.", "-" },
    { "li", "|cffffd100Lugar|r: define el tinte, la viñeta y el grano. Orden: mazmorra o banda, interior, clima (lluvia, nieve, tormenta de arena) y luego el tipo de zona: tierras templadas, desiertos y tierras áridas, tierras nevadas, jungla y pantano, tierras corruptas, tierras volcánicas, bosques arcanos. Una zona aún desconocida cuenta como templada. El clima solo cuenta si la Intensidad del clima es superior a 0.", "-" },
    { "li", "|cffffd100Hora del día|r: define el cielo (día, amanecer y atardecer, noche). La noche sigue el día y la noche del juego; el amanecer y el atardecer, la hora del servidor. Sin cielo en interiores ni en mazmorras.", "-" },
    { "li", "La línea de la derecha muestra el lugar y la hora del día detectados ahora. Cuando una mazmorra, un interior o el clima pasan antes que una zona que has ajustado, lo indica.", "-" },
    { "li", "|cffffd100Contexto a editar|r: elige un contexto y ajusta sus filtros debajo. El botón Predeterminado devuelve el valor incluido para ese contexto. El menú tiene cinco grupos: |cffffd100Zonas|r (la zona en la que estás y las que has ajustado), |cffffd100Mazmorra e interior|r, |cffffd100Clima|r, |cffffd100Tipo de zona|r y |cffffd100Cielo (hora)|r. Los cuatro primeros ajustan el tinte, la viñeta, el grano y un preajuste gráfico: solo se aplica un lugar a la vez, en el orden indicado arriba. El último ajusta el cielo. No hace falta ajustar nada para empezar: cada contexto ya tiene sus valores.", "-" },
    { "li", "|cffffd100Esta zona|r: primera opción del mismo menú, con el nombre de la zona en la que estás. Elígela para dar a esta zona su propio tinte, viñeta y grano, partiendo de su tipo de zona. Pasa entonces antes del tipo de zona, pero después de mazmorra, interior y clima. Las zonas que ajustas siguen en el menú. |cffffd100Tipo de zona|r elimina los valores de la zona: vuelve a seguir su tipo de zona.", "-" },
    { "li", "|cffffd100Todas las zonas|r: submenú del mismo menú, con todas las zonas conocidas. Elige una para ajustarla sin estar allí. Las zonas están ordenadas por continente.", "-" },
    { "li", "|cffffd100Preajuste|r y |cffffd100Distancia del escenario|r (primeras líneas de un lugar o de una zona): se aplican mientras estás en ese lugar, por encima de tus propios ajustes, con el ambiente automático activado o no. La distancia del escenario del lugar va antes que la del preajuste. Tus propios ajustes se conservan y vuelven cuando te vas. |cffffd100Mis ajustes|r no cambia nada. Ejemplo: Bajo en mazmorras, Extra en una zona que te gusta. En una mazmorra o banda, la primera opción del menú ajusta solo esa mazmorra. En la pestaña Calidad, el botón |cffffd100Por lugar|r abre estas líneas para el lugar donde estás; muestra |cffffd100Aquí: …|r mientras un lugar aplica los suyos. En combate, el cambio espera al final del combate.", "-" },
    { "li", "|cffffd100Mi filtro|r (primera línea de los filtros de un lugar o de una zona): ese lugar usa uno de tus filtros de la pestaña Mis filtros, con su contraste, su brillo y su gamma, mientras el ambiente automático está activado.", "-" },
    { "li", "|cffffd100Día y noche|r (modo |cffffd100Día y noche automáticos|r): Panorama aplica el |cffffd100Tono diurno|r de día y el |cffffd100Tono nocturno|r de noche, según el día y la noche del juego. Sustituyen al tono de la pestaña Filtros. El cambio es gradual de 19:00 a 21:00 y de 5:00 a 7:00 (hora del servidor). Los tonos diurno y nocturno y sus intensidades se definen con Ajustes avanzados.", "-" },
    { "h2", "5. Mis filtros" },
    { "p", "La pestaña Mis filtros (visible con Ajustes avanzados) sirve para crear tantos filtros propios como quieras. |cffffd100Nuevo|r añade uno, |cffffd100Eliminar|r quita el filtro abierto: la pestaña Filtros, los lugares y las zonas que lo usaban vuelven a Ninguno." },
    { "li", "|cffffd100Filtro a editar|r: elige el filtro que ajustan las líneas de abajo. |cffffd100Nombre|r: ponle un nombre (Intro para confirmar).", "-" },
    { "li", "|cffffd100Rojo|r, |cffffd100Verde|r, |cffffd100Azul|r (en %): color del tono del filtro. |cffffd100Intensidad del tono|r: su fuerza.", "-" },
    { "li", "|cffffd100Viñeta|r y |cffffd100Grano|r: los del filtro.", "-" },
    { "li", "|cffffd100Contraste|r, |cffffd100Brillo|r, |cffffd100Gamma|r: ajustes de imagen que el filtro da al juego mientras está aplicado; después vuelven tus propios valores. Mis ajustes: no cambia nada. Según el modo de pantalla, pueden no tener efecto.", "-" },
    { "li", "Mientras la pestaña está abierta, el filtro mostrado se ve en directo en el juego.", "-" },
    { "li", "Para usar un filtro: elígelo en la línea |cffffd100Mi filtro|r de la pestaña Filtros (en todas partes), o de un lugar o una zona en la pestaña Ambiente (ambiente automático activado). Entonces sustituye el tono, la viñeta y el grano, cuyas líneas quedan en gris. Ninguno: no cambia nada.", "-" },
    { "h2", "6. Tus valores y el juego" },
    { "li", "En la primera instalación, Panorama lee tus ajustes actuales del juego. No cambia nada hasta que muevas un control.", "-" },
    { "li", "Un cambio hecho en el menú de Gráficos del juego o con |cffffd100/console|r se muestra en la ventana.", "-" },
    { "li", "|cffffd100Aplicar en cada conexión|r (pie, activado por defecto): los ajustes que cambiaste en Panorama se escriben de nuevo en cada conexión. Los demás siguen el menú de Gráficos del juego.", "-" },
    { "li", "Un cambio hecho durante el combate se aplica cuando termina el combate.", "-" },
    { "li", "Algunos ajustes, como MSAA, necesitan reiniciar los gráficos. Haz clic en |cffffd100Reiniciar|r en el pie o escribe |cffffd100/pano restart|r. La pantalla parpadea un segundo.", "-" },
    { "h2", "7. HDR en Windows" },
    { "p", "Los ajustes de HDR existen en el juego solo como comandos de consola. Panorama los muestra en la pestaña |cffffd100Avanzado|r, sección |cffffd100HDR (solo consola)|r. Necesitas un monitor compatible con HDR." },
    { "h3", "Paso 1: activar HDR en Windows" },
    { "p", "Windows 11:" },
    { "li", "Abre |cffffd100Configuración > Sistema > Pantalla|r.", "1." },
    { "li", "Selecciona el monitor HDR si tienes más de uno.", "2." },
    { "li", "Activa |cffffd100Usar HDR|r. El atajo |cffffd100Win + Alt + B|r también lo activa o desactiva.", "3." },
    { "p", "Windows 10: |cffffd100Configuración > Sistema > Pantalla > Configuración de color HD de Windows|r (Windows HD Color settings), y luego activa |cffffd100Reproducir juegos y aplicaciones HDR|r (Play HDR games and apps)." },
    { "p", "Comprueba también que HDR esté activado en el menú propio del monitor, si tiene esa opción." },
    { "p", "Desactiva el |cffffd100HDR automático|r (Auto HDR) de Windows 11: |cffffd100Configuración > Sistema > Pantalla > HDR|r. Sirve para juegos sin HDR. WoW genera su propia imagen HDR." },
    { "h3", "Paso 2: encontrar el brillo máximo de tu monitor" },
    { "p", "Instala la aplicación gratuita |cffffd100Calibración de HDR de Windows|r (Windows HDR Calibration) desde la Microsoft Store y ejecútala. La luminancia máxima que encuentra es el brillo máximo de tu monitor, en nits." },
    { "p", "Sin la aplicación, usa la clasificación HDR del monitor: DisplayHDR 400 significa unos 400 nits, DisplayHDR 600 unos 600, DisplayHDR 1000 unos 1000." },
    { "h3", "Paso 3: configurar HDR en Panorama" },
    { "p", "Abre |cffffd100/pano|r, pestaña |cffffd100Avanzado|r, sección |cffffd100HDR (solo consola)|r." },
    { "li", "Marca |cffffd100Salida HDR|r.", "1." },
    { "li", "Marca |cffffd100Usar brillo máximo|r o |cffffd100Usar brillo de referencia|r: uno u otro, nunca los dos. Sin ninguno, la imagen se oscurece.", "2." },
    { "p", "|cffffd100Modo de brillo máximo (recomendado)|r" },
    { "li", "Marca |cffffd100Usar brillo máximo|r.", "-" },
    { "li", "Ajusta |cffffd100Brillo máximo (nits)|r al valor encontrado en el paso 2.", "-" },
    { "li", "|cffffd100Intensidad HDR|r solo funciona en este modo. El valor predeterminado del juego es 2. Cámbialo en pasos pequeños y compara: Blizzard no documenta su efecto exacto.", "-" },
    { "p", "|cffffd100Modo de brillo de referencia|r" },
    { "li", "Marca |cffffd100Usar brillo de referencia|r.", "-" },
    { "li", "|cffffd100Brillo de referencia (nits)|r es el brillo del blanco en la escena. 203 es el valor estándar. Súbelo si la imagen se ve demasiado oscura en una habitación luminosa. Intensidad HDR no tiene efecto en este modo.", "-" },
    { "p", "Si la imagen no cambia, haz clic en |cffffd100Reiniciar|r en el pie." },
    { "h3", "Solución de problemas de HDR" },
    { "row", "Imagen muy oscura", "Marca uno de los dos modos de brillo." },
    { "row", "Imagen gris o deslavada", "Activa HDR en Windows (paso 1) y en el menú del monitor." },
    { "row", "HDR automático activado en Windows", "Desactívalo (paso 1)." },
    { "row", "Luces demasiado brillantes o planas", "Ajusta el brillo máximo al valor real de tu monitor (paso 2)." },
    { "row", "Quieres desactivar HDR", "Desmarca |cffffd100Salida HDR|r." },
    { "p", "Cada línea de HDR tiene un botón Predeterminado que restaura el valor del juego." },
    { "h2", "8. Comandos" },
    { "row", "|cffffd100/pano|r", "Abrir o cerrar la ventana" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Aplicar un preajuste" },
    { "row", "|cffffd100/pano undo|r", "Deshacer el último cambio" },
    { "row", "|cffffd100/pano redo|r", "Rehacer el cambio que acabas de deshacer" },
    { "row", "|cffffd100/pano reset|r", "Devolver cada ajuste y cada filtro a su valor por defecto" },
    { "row", "|cffffd100/pano status|r", "Muestra en el chat el lugar y el momento detectados y los filtros aplicados ahora (durante un fundido, los valores de destino)" },
    { "row", "|cffffd100/pano apply|r", "Escribir de nuevo los ajustes cambiados en Panorama" },
    { "row", "|cffffd100/pano restart|r", "Reiniciar el motor gráfico" },
    { "row", "|cffffd100/pano minimap|r", "Mostrar u ocultar el botón del minimapa" },
    { "h2", "9. Restablecer" },
    { "li", "El botón |cffffd100Predeterminado|r de cada línea restablece ese ajuste.", "-" },
    { "li", "El botón |cffffd100Predeterminado|r del menú de Gráficos del juego restablece solo los ajustes que gestiona ese menú, y Panorama lo sigue. Usa los botones Predeterminado de |cffffd100/pano|r para los demás y para los filtros.", "-" },
    { "li", "|cffffd100Restablecer todo|r (pie, con confirmación) o |cffffd100/pano reset|r: devuelve cada ajuste cambiado en Panorama y cada filtro a su valor por defecto. |cffffd100Deshacer|r lo anula hasta |cffffd100/reload|r. La pestaña Ambiente y las zonas ajustadas también se restablecen. Tus filtros de la pestaña Mis filtros también se borran.", "-" },
}
NS.guides.esMX = NS.guides.esES
